    {
        if(!st.size() || ele>st.top()) 
        {
        st.push(ele);
        return;  
        }
        int e1 = st.top();

        if( ele < e1)
         { 
            st.pop(); 
            SortExplored(ele, st);
            st.push(e1);

         }
         else st.push(ele);  


